Xây dựng lớp Clock để vẽ đồng hồ số
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.Date;
import java.util.GregorianCalendar;
import java.util.TimeZone;
import java.util.logging.Level;
import java.util.logging.Logger;
import javax.swing.JPanel;
public class Clock extends Thread{
  private JPanel jp;
  private final String city;
  private GregorianCalendar calendar;
  private int seconds=0;
  public Clock(JPanel jp, String city, String timezone) {
       this.jp = jp;
       this.city = city;
       calendar                      =                new
  GregorianCalendar(TimeZone.getTimeZone(timezone));
       this.start();
  }
  public void paint(){
       Graphics g = jp.getGraphics();
       Graphics2D g2d = (Graphics2D) g;
       calendar.setTime(new Date());
       seconds=
                 calendar.get(calendar.HOUR)*60*60+
                 calendar.get(calendar.MINUTE)*60+
                 calendar.get(calendar.SECOND);

     g.setColor(Color.RED);
     g.setFont(new Font("Times NewRoman",
                 Font.BOLD, 16));
     int x,y;
     int x0=5,y0=5;
     int xr=95+ x0,yr=107+y0;
     g.drawOval(0, 0, 210, 210);
     g.setColor(Color.WHITE);
     g.fillOval(x0, y0, 200, 200);
     g.setColor(Color.RED);
     double anpha;
     for (int i = 1; i <= 12; i++) {
        anpha = i*30*Math.PI/180;
        x = xr+(int) Math.round(90*Math.sin(anpha));
        y = yr-(int) Math.round(90*Math.cos(anpha));
        g.drawString(String.valueOf(i), x, y);
     }
     g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
                 RenderingHints.VALUE_ANTIALIAS_ON);
     double hourAngle = 2 * Math.PI *
            (seconds - 3 * 60 * 60) / (12 * 60 * 60);
     double minuteAngle = 2 * Math.PI *
            (seconds - 15 * 60) / (60 * 60);
     double secondAngle = 2 * Math.PI *
            (seconds - 15) / 60;
     g.setColor(Color.red);
     g.drawLine(100, 100, 100 +
            (int) (40 * Math.cos(hourAngle)), 100 +
            (int) (40 * Math.sin(hourAngle)));
     g.setColor(Color.BLUE);
     g.drawLine(100, 100, 100 +
            (int) (60 * Math.cos(minuteAngle)), 100 +
            (int) (60 * Math.sin(minuteAngle)));
     g.setColor(Color.MAGENTA);
     g.drawLine(100, 100, 100 +
            (int) (80 * Math.cos(secondAngle)), 100 +
            (int) (80 * Math.sin(secondAngle)));

          g.setColor(Color.BLUE);
          g.drawString(city, 80, 230);
      }
      public void run(){
         while (true) {
           try {
              Thread.sleep(1000);
              paint();
           }catch (InterruptedException ex) {
               Logger.getLogger(Clock.class.getName()).
                           log(Level.SEVERE, null, ex);
           }
         }
      }
  }

